package edu.pe.cibertec.saibm.libro.application;
import static org.assertj.core.api.Assertions.*; import java.util.*; import org.junit.jupiter.api.Test; import edu.pe.cibertec.saibm.libro.application.port.in.BookUseCase; import edu.pe.cibertec.saibm.libro.application.port.out.*; import edu.pe.cibertec.saibm.libro.application.usecase.BookService; import edu.pe.cibertec.saibm.libro.domain.model.Book;
class BookUseCaseTest { final Repo repo=new Repo(); final List<Object> events=new ArrayList<>(); final BookUseCase use=new BookService(repo,events::add); @Test void createsAndSearchesActiveBooks(){var made=use.create(new BookUseCase.Create("Java","","Ada",""));repo.save(Book.create(UUID.randomUUID(),"Hidden","","Alan","").deactivate());var p=use.search(new BookUseCase.Search("java",0,10));assertThat(made.id()).isNotNull();assertThat(p.content()).extracting(BookUseCase.View::title).containsExactly("Java");assertThat(events).hasSize(1);} @Test void updatesAndDeactivates(){var made=use.create(new BookUseCase.Create("Java","","Ada",""));var changed=use.update(made.id(),new BookUseCase.Update("Java 2","","Grace",""));use.deactivate(changed.id());assertThat(repo.find(changed.id())).get().extracting(Book::active).isEqualTo(false);} static class Repo implements BookRepositoryPort {final List<Book> all=new ArrayList<>();public Optional<Book> find(UUID id){return all.stream().filter(b->b.id().equals(id)).findFirst();}public Book save(Book b){all.removeIf(x->x.id().equals(b.id()));all.add(b);return b;}public Page search(String q,int p,int s){var f=all.stream().filter(Book::active).filter(b->q.isBlank()||(b.title()+" "+b.author()).toLowerCase().contains(q.toLowerCase())).toList();return new Page(f,p,s,f.size());}} }
